<script setup lang="ts">defineProps<{page:number;totalPages:number}>();defineEmits<{(e:"change",page:number):void}>();</script><template><nav class="acme-pagination" aria-label="分頁"><button :disabled="page===1" @click="$emit('change',Math.max(1,page-1))">‹</button><button v-for="p in Math.min(totalPages,7)" :key="p" :aria-current="p===page?'page':undefined" @click="$emit('change',p)">{{p}}</button><button :disabled="page===totalPages" @click="$emit('change',Math.min(totalPages,page+1))">›</button></nav></template>